import{_ as i,c as e,o as s,a2 as l}from"./chunks/framework.mqLGQ42V.js";const u=JSON.parse('{"title":"调试面板 (Debug Panel) - Rive 脚本","description":"脚本 (Scripting) 使用调试面板诊断脚本问题。","frontmatter":{"title":"调试面板 (Debug Panel) - Rive 脚本","description":"脚本 (Scripting) 使用调试面板诊断脚本问题。","head":[["meta",{"name":"keywords","content":"Rive, Rive 中文文档, Rive 脚本, 调试, 调试面板"}]]},"headers":[],"relativePath":"scripting/debugging/debug-panel.md","filePath":"scripting/debugging/debug-panel.md","lastUpdated":1774838907000}'),n={name:"scripting/debugging/debug-panel.md"};function t(r,a,h,o,p,d){return s(),e("div",null,[...a[0]||(a[0]=[l(`<p>脚本 (Scripting)</p><h1 id="调试面板-debug-panel" tabindex="-1">调试面板 (Debug Panel) <a class="header-anchor" href="#调试面板-debug-panel" aria-label="Permalink to &quot;调试面板 (Debug Panel)&quot;">​</a></h1><p>使用调试面板诊断脚本问题。</p><h2 id="​-概览" tabindex="-1"><a href="#overview">​</a> 概览 <a class="header-anchor" href="#​-概览" aria-label="Permalink to &quot;[​](#overview) 概览&quot;">​</a></h2><p>Rive 编辑器内置了调试工具，帮助你开发和调试脚本。</p><h2 id="​-访问调试面板" tabindex="-1"><a href="#accessing-debug-panel">​</a> 访问调试面板 <a class="header-anchor" href="#​-访问调试面板" aria-label="Permalink to &quot;[​](#accessing-debug-panel) 访问调试面板&quot;">​</a></h2><ol><li>在编辑器中打开你的 Rive 文件</li><li>点击底部工具栏的 <strong>Debug</strong> 按钮</li><li>调试面板将显示在编辑器底部</li></ol><h2 id="​-功能" tabindex="-1"><a href="#features">​</a> 功能 <a class="header-anchor" href="#​-功能" aria-label="Permalink to &quot;[​](#features) 功能&quot;">​</a></h2><h3 id="控制台输出" tabindex="-1">控制台输出 <a class="header-anchor" href="#控制台输出" aria-label="Permalink to &quot;控制台输出&quot;">​</a></h3><p>脚本中的 <code>console.log()</code> 输出将显示在调试面板中：</p><div class="language-javascript vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">console.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">log</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;调试信息&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">console.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">warn</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;警告信息&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">console.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">error</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;错误信息&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><h3 id="变量监视" tabindex="-1">变量监视 <a class="header-anchor" href="#变量监视" aria-label="Permalink to &quot;变量监视&quot;">​</a></h3><p>你可以监视脚本变量的值：</p><ol><li>在调试面板中点击 <strong>Add Watch</strong></li><li>输入变量名</li><li>变量值将实时更新</li></ol><h3 id="断点" tabindex="-1">断点 <a class="header-anchor" href="#断点" aria-label="Permalink to &quot;断点&quot;">​</a></h3><p>在脚本中添加断点以暂停执行：</p><ol><li>在代码行号旁点击设置断点</li><li>当执行到断点时，脚本将暂停</li><li>你可以检查当前变量状态</li></ol><h2 id="​-常见问题" tabindex="-1"><a href="#common-issues">​</a> 常见问题 <a class="header-anchor" href="#​-常见问题" aria-label="Permalink to &quot;[​](#common-issues) 常见问题&quot;">​</a></h2><h3 id="脚本不执行" tabindex="-1">脚本不执行 <a class="header-anchor" href="#脚本不执行" aria-label="Permalink to &quot;脚本不执行&quot;">​</a></h3><ul><li>确保脚本已正确附加到节点</li><li>检查状态机是否正在运行</li></ul><h3 id="控制台无输出" tabindex="-1">控制台无输出 <a class="header-anchor" href="#控制台无输出" aria-label="Permalink to &quot;控制台无输出&quot;">​</a></h3><ul><li>确保 <code>console.log</code> 语句语法正确</li><li>检查调试面板是否打开</li></ul><p><a href="/docs/scripting/creating-scripts">创建脚本</a><a href="/docs/scripting/overview">脚本概览</a></p>`,23)])])}const g=i(n,[["render",t]]);export{u as __pageData,g as default};
